const execution = $json.execution;
const workflow  = $json.workflow;

let filePath = 'unknown';
let source   = 'unknown';

try {
  const webhookRun = execution.data?.resultData?.runData?.['Webhook'];
  if (webhookRun?.[0]?.data?.main?.[0]?.[0]?.json?.body) {
    const body = webhookRun[0].data.main[0][0].json.body;
    filePath = body.filePath || 'unknown';
    source   = body.source   || 'library';
  }
} catch (_) {}

return [{
  json: {
    filePath,
    source,
    n8nExecutionId: String(execution.id  || ''),
    failedStep:     execution.lastNodeExecuted || execution.error?.node?.name || 'unknown',
    errorMessage:   execution.error?.message  || 'Unknown error',
    workflowName:   workflow.name || '',
  }
}];
